package com.bocsoft.sqleditor.export;
import com.bocsoft.sqleditor.config.SqlEditorProperties;import java.io.ByteArrayOutputStream;import java.nio.charset.StandardCharsets;import java.util.Arrays;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.*;
class CsvEncoderTest {@Test void encodesRfc4180Utf8NullAndFormulaProtection()throws Exception{SqlEditorProperties p=new SqlEditorProperties();CsvEncoder csv=new CsvEncoder(p);ByteArrayOutputStream out=new ByteArrayOutputStream();csv.bom(out);csv.record(out,Arrays.asList("中文,逗号","a\"b","line\nnext",null,"=SUM(A1:A2)"));byte[]bytes=out.toByteArray();assertThat(Arrays.copyOf(bytes,3)).containsExactly((byte)0xef,(byte)0xbb,(byte)0xbf);String text=new String(bytes,3,bytes.length-3,StandardCharsets.UTF_8);assertThat(text).isEqualTo("\"中文,逗号\",\"a\"\"b\",\"line\nnext\",,'=SUM(A1:A2)\r\n");}}
